window.kbPageData["views/entry/k-841486135b59aa6b"] = {"key":"entry/k-841486135b59aa6b","state":{"route":"entry/k-841486135b59aa6b"},"node":{"id":"k-841486135b59aa6b","mode":"k","title":"2022年我国水电、风电、太阳能发电和生物质发电装机均居世界首位","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2023 A类 行测#1"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"截至2022年底，我国水电、风电、太阳能发电和生物质发电的累计装机容量均居世界首位。","review":{"definition":"截至2022年底，我国水电、风电、太阳能发电和生物质发电的累计装机容量均居世界首位。","explanation":"题中②比较的是四类电源各自的累计装机容量。国家能源局2023年1月16日发布的全国电力工业统计给出了国内装机数据，未列四类电源的国际排名。该局2月发布会明确了年末统计时点，生物质发电装机为0.41亿千瓦。同年6月，国家能源局新能源司副司长在两项2022年行业报告发布时确认四类电源分别连续18年、13年、8年和5年位居全球装机首位，支持选项B所含的②。","references":[{"source":"web-84d2852d99c1eed2","location":"正文第二段","quote":"截至12月底，全国累计发电装机容量约25.6亿千瓦"},{"source":"web-73dea1cc3202db89","location":"王大鹏发布2022年可再生能源发展情况，第一部分","quote":"生物质发电0.41亿千瓦"},{"source":"web-74eb8de19dc37eea","location":"末段，国家能源局新能源司副司长熊敏峰介绍","quote":"分别连续18年、13年、8年和5年稳居全球装机首位"}],"evidence":"水电、风电、太阳能发电、生物质发电装机均居世界第一","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 A类 行测#1":{"paper":"江苏 2023 A类 行测","n":1,"mod":"常识判断","src":["22304fe4c340e19d7902.pdf",1],"asrc":["be17f9afe070cf13a0fb.pdf",1],"card":"8908824394fc08bc163ef39f","links":[{"id":"k-841486135b59aa6b","role":"直接考查","why":"四类电源的装机位次共同决定该项成就表述是否成立。"}]}},"terms":{},"references":{"web-84d2852d99c1eed2":{"name":"《国家能源局发布2022年全国电力工业统计数据》（中国政府网转载）","url":"https://app.www.gov.cn/govdata/gov/202301/19/496401/article.html"},"web-73dea1cc3202db89":{"name":"国家能源局2023年2月13日例行新闻发布会文字实录","url":"https://www.nea.gov.cn/2023-02/13/c_1310697026.htm"},"web-74eb8de19dc37eea":{"name":"《抽水蓄能已建在建装机规模1.6亿千瓦》（国家能源局网站转载）","url":"https://www.nea.gov.cn/2023-06/30/c_1310730336.htm"}},"topics":[],"units":{"k-841486135b59aa6b":[["江苏 2023 A类 行测#1"]]}};
